775: pub(crate) fn infer_grpc_status(
776:     trailers: Option<&HeaderMap>,
777:     status_code: http::StatusCode,
778: ) -> Result<(), Option<Status>> {
779:     if let Some(trailers) = trailers {
780:         if let Some(status) = Status::from_header_map(trailers) {
781:             if status.code() == Code::Ok {
782:                 return Ok(());
783:             } else {
784:                 return Err(status.into());
785:             }
786:         }
787:     }
788:     trace!("trailers missing grpc-status");
789:     let code = match status_code {
790:         // Borrowed from https://github.com/grpc/grpc/blob/master/doc/http-grpc-status-mapping.md
791:         http::StatusCode::BAD_REQUEST => Code::Internal,
792:         http::StatusCode::UNAUTHORIZED => Code::Unauthenticated,
793:         http::StatusCode::FORBIDDEN => Code::PermissionDenied,
794:         http::StatusCode::NOT_FOUND => Code::Unimplemented,
795:         http::StatusCode::TOO_MANY_REQUESTS
796:         | http::StatusCode::BAD_GATEWAY
797:         | http::StatusCode::SERVICE_UNAVAILABLE
798:         | http::StatusCode::GATEWAY_TIMEOUT => Code::Unavailable,
799:         // We got a 200 but no trailers, we can infer that this request is finished.
800:         //
801:         // This can happen when a streaming response sends two Status but
802:         // gRPC requires that we end the stream after the first status.
803:         //
804:         // https://github.com/hyperium/tonic/issues/681
805:         http::StatusCode::OK => return Err(None),
806:         _ => Code::Unknown,
807:     };
808: 
809:     let msg = format!(
810:         "grpc-status header missing, mapped from HTTP status code {}",
811:         status_code.as_u16(),
812:     );
813:     let status = Status::new(code, msg);
814:     Err(status.into())
815: }

294:     fn response(&mut self) -> Result<(), Status> {
295:         if let Direction::Response(status) = self.direction {
296:             if let Err(Some(e)) = crate::status::infer_grpc_status(self.trailers.as_ref(), status) {
297:                 // If the trailers contain a grpc-status, then we should return that as the error
298:                 // and otherwise stop the stream (by taking the error state)
299:                 self.trailers.take();
300:                 return Err(e);
301:             }
302:         }
303:         Ok(())
304:     }
